using System.Buffers;
using System.Buffers.Text;

namespace Brutal.Extensions;

public static class BoolExtensions
{
    /// <inheritdoc cref="Utf8Formatter.TryFormat(bool,Span{byte},out int,StandardFormat)"/>
    /// <remarks>
    /// bool doesn't implement IUtf8SpanFormattable for some reason: this emulates it, to simplify our autogenerated code.
    /// Also, this handles the G/l formats, which non-UTF8 formatting doesn't handle:
    /// https://learn.microsoft.com/en-us/dotnet/api/system.buffers.text.utf8formatter.tryformat?view=net-9.0#system-buffers-text-utf8formatter-tryformat(system-boolean-system-span((system-byte))-system-int32@-system-buffers-standardformat)
    /// </remarks>
    public static bool TryFormat(
        this bool value,
        Span<byte> destination,
        out int bytesWritten,
        ReadOnlySpan<char> format = default
    )
    {
        return Utf8Formatter.TryFormat(value, destination, out bytesWritten, StandardFormat.Parse(format));
    }

    /// <inheritdoc cref="TryFormat(bool,Span{char},out int,StandardFormat)"/>
    public static bool TryFormat(
        this bool value,
        Span<char> destination,
        out int charsWritten,
        ReadOnlySpan<char> format = default
    )
    {
        return TryFormat(value, destination, out charsWritten, StandardFormat.Parse(format));
    }

    /// <inheritdoc cref="Utf8Formatter.TryFormat(bool,Span{byte},out int,StandardFormat)"/>
    /// <remarks>
    /// bool doesn't implement ISpanFormattable for some reason: this emulates it, to simplify our autogenerated code.
    /// Also, this handles the G/l formats, which non-UTF8 formatting doesn't handle:
    /// https://learn.microsoft.com/en-us/dotnet/api/system.buffers.text.utf8formatter.tryformat?view=net-9.0#system-buffers-text-utf8formatter-tryformat(system-boolean-system-span((system-byte))-system-int32@-system-buffers-standardformat)
    /// </remarks>
    public static bool TryFormat(
        this bool value,
        Span<char> destination,
        out int charsWritten,
        StandardFormat format = default
    )
    {
        // Copied from https://github.com/dotnet/runtime/blob/main/src/libraries/System.Private.CoreLib/src/System/Buffers/Text/Utf8Formatter/Utf8Formatter.Boolean.cs
        // and adapted from Span<byte> to Span<char>.

        char symbol = FormattingHelpers.GetSymbolOrDefault(format, 'G');

        if (value)
        {
            if (symbol == 'G')
            {
                if (!"True".TryCopyTo(destination))
                {
                    goto BufferTooSmall;
                }
            }
            else if (symbol == 'l')
            {
                if (!"true".TryCopyTo(destination))
                {
                    goto BufferTooSmall;
                }
            }
            else
            {
                goto BadFormat;
            }

            charsWritten = 4;
            return true;
        }
        else
        {
            if (symbol == 'G')
            {
                if (!"False".TryCopyTo(destination))
                {
                    goto BufferTooSmall;
                }
            }
            else if (symbol == 'l')
            {
                if (!"false".TryCopyTo(destination))
                {
                    goto BufferTooSmall;
                }
            }
            else
            {
                goto BadFormat;
            }

            charsWritten = 5;
            return true;
        }

        BadFormat:
        {
            //ThrowHelper.ThrowFormatException_BadFormatSpecifier();
            throw new FormatException("Format specifier was invalid.");
        }

        BufferTooSmall:
        {
            charsWritten = 0;
            return false;
        }
    }

    // Copied from internal: https://github.com/dotnet/runtime/blob/main/src/libraries/System.Private.CoreLib/src/System/Buffers/Text/Utf8Formatter/FormattingHelpers.cs
    static class FormattingHelpers
    {
        /// <summary>
        /// Returns the symbol contained within the standard format. If the standard format
        /// has not been initialized, returns the provided fallback symbol.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static char GetSymbolOrDefault(in StandardFormat format, char defaultSymbol)
        {
            // This is equivalent to the line below, but it is written in such a way
            // that the JIT is able to perform more optimizations.
            //
            // return (format.IsDefault) ? defaultSymbol : format.Symbol;

            char symbol = format.Symbol;
            if (symbol == default && format.Precision == default)
            {
                symbol = defaultSymbol;
            }
            return symbol;
        }
    }
}
